package dev.industrialtechnology.client.space;
import net.minecraftforge.client.IRenderHandler;import net.minecraft.client.Minecraft;import net.minecraft.client.multiplayer.WorldClient;import net.minecraft.client.renderer.Tessellator;import net.minecraft.util.ResourceLocation;import org.lwjgl.opengl.GL11;import java.util.Random;import dev.industrialtechnology.space.*;
public final class PlanetSky extends IRenderHandler {
    private static final ResourceLocation EARTH=new ResourceLocation("industrialtech:textures/environment/earth.png"),SUN=new ResourceLocation("textures/environment/sun.png");private final double[] stars=new double[512*3];
    public PlanetSky(){Random r=new Random(7710);for(int i=0;i<512;i++){double a=r.nextDouble()*Math.PI*2,z=r.nextDouble()*2-1,d=Math.sqrt(1-z*z)*100;stars[i*3]=Math.cos(a)*d;stars[i*3+1]=z*100;stars[i*3+2]=Math.sin(a)*d;}}
    private static void quad(double half){Tessellator t=Tessellator.instance;t.startDrawingQuads();t.addVertexWithUV(-half,100,-half,0,0);t.addVertexWithUV(-half,100,half,0,1);t.addVertexWithUV(half,100,half,1,1);t.addVertexWithUV(half,100,-half,1,0);t.draw();}
    @Override public void render(float partial,WorldClient world,Minecraft mc){render(partial,world,mc,false);}
    public void renderBehindTerrain(float partial,WorldClient world,Minecraft mc){render(partial,world,mc,true);}
    private void render(float partial,WorldClient world,Minecraft mc,boolean behind){boolean mars=world.provider.dimensionId==SpaceConfig.mars;int active=GL11.glGetInteger(org.lwjgl.opengl.GL13.GL_ACTIVE_TEXTURE);GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();try{GL11.glScalef(.3f,.3f,.3f);if(behind){GL11.glEnable(GL11.GL_DEPTH_TEST);GL11.glDepthFunc(GL11.GL_LEQUAL);GL11.glDepthRange(1,1);}else GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDisable(GL11.GL_ALPHA_TEST);net.minecraft.client.renderer.OpenGlHelper.setActiveTexture(net.minecraft.client.renderer.OpenGlHelper.lightmapTexUnit);GL11.glDisable(GL11.GL_TEXTURE_2D);net.minecraft.client.renderer.OpenGlHelper.setActiveTexture(net.minecraft.client.renderer.OpenGlHelper.defaultTexUnit);GL11.glDisable(GL11.GL_LIGHTING);GL11.glDisable(GL11.GL_FOG);GL11.glDisable(GL11.GL_CULL_FACE);GL11.glDepthMask(false);GL11.glEnable(GL11.GL_BLEND);GL11.glBlendFunc(GL11.GL_SRC_ALPHA,GL11.GL_ONE_MINUS_SRC_ALPHA);GL11.glDisable(GL11.GL_TEXTURE_2D);
        float day=Math.max(.12f,world.getSunBrightness(partial));GL11.glColor4f(mars?.50f*day:0,mars?.28f*day:0,mars?.18f*day:0,1);Tessellator t=Tessellator.instance;t.startDrawingQuads();t.addVertex(-200,-10,-200);t.addVertex(-200,-10,200);t.addVertex(200,-10,200);t.addVertex(200,-10,-200);t.draw();
        float brightness=mars?world.getStarBrightness(partial):.85f;GL11.glColor4f(brightness,brightness,brightness,1);GL11.glPointSize(1.5f);GL11.glBegin(GL11.GL_POINTS);for(int i=0;i<512;i++)GL11.glVertex3d(stars[i*3],stars[i*3+1],stars[i*3+2]);GL11.glEnd();
        GL11.glEnable(GL11.GL_TEXTURE_2D);GL11.glColor4f(1,1,1,1);GL11.glPushMatrix();GL11.glRotatef(world.getCelestialAngle(partial)*360,1,0,0);mc.getTextureManager().bindTexture(SUN);quad(mars?8:12);GL11.glPopMatrix();
        if(!mars&&mc.thePlayer!=null){double longitude=mc.thePlayer.posX/65536.0*Math.PI*2,latitude=Math.max(-1.4,Math.min(1.4,mc.thePlayer.posZ/65536.0*Math.PI));double near=Math.cos(longitude)*Math.cos(latitude);if(near>.05){GL11.glPushMatrix();GL11.glRotatef(30,0,1,0);GL11.glRotatef((float)(Math.acos(near)*180/Math.PI+25),1,0,0);mc.getTextureManager().bindTexture(EARTH);quad(5);GL11.glPopMatrix();}}
    }finally{GL11.glPopMatrix();GL11.glPopAttrib();net.minecraft.client.renderer.OpenGlHelper.setActiveTexture(active);GL11.glColor4f(1,1,1,1);}}
}
